#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# W009 A as built: monerodato.2 native wallet-rpc (dot2) vs the dot3-prep branch native build (dot3).
# Same offline daemon; separate copies of the same frozen wallet. n = 8, 32, 128; 3 rounds; arm order alternating.
set -u
D=$HOME/work/wprof; cd $D
W2=$HOME/work/monerodato/build/native/bin/monero-wallet-rpc
W3=$HOME/work/monerodato-dot3/build/native/bin/monero-wallet-rpc
gov0=$(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)
sudo cpupower frequency-set -g performance > /dev/null
rm -rf wallets_dot3 && mkdir -p wallets_dot3 && chmod 700 wallets_dot3 && cp -p wallets/w006 wallets/w006.keys wallets_dot3/
start() { # bin dir port tag
  $1 --testnet --wallet-dir $D/$2 --daemon-address 127.0.0.1:28481 --trusted-daemon --rpc-bind-ip 127.0.0.1 --rpc-bind-port $3 \
    --disable-rpc-login --non-interactive --log-file $D/wrpc_$4.log --log-level "*:WARNING" > $D/wrpc_$4.stdout 2>&1 &
  echo $! > wrpc_$4.pid
  for i in $(seq 1 60); do curl -s -m 3 http://127.0.0.1:$3/json_rpc -d "{\"jsonrpc\":\"2.0\",\"id\":0,\"method\":\"get_version\"}" | grep -q result && break; sleep 1; done
}
start $W2 wallets 28483 abdot2
start $W3 wallets_dot3 28487 abdot3
echo "dot2 $(sha256sum $W2 | cut -c1-16) pid $(cat wrpc_abdot2.pid); dot3 $(sha256sum $W3 | cut -c1-16) pid $(cat wrpc_abdot3.pid); governor $gov0 -> performance; load $(cut -d" " -f1-3 /proc/loadavg)"
for r in 1 2 3; do
  if [ $((r % 2)) = 1 ]; then order="dot3 dot2"; else order="dot2 dot3"; fi
  for arm in $order; do
    if [ $arm = dot2 ]; then P=28483; PID=$(cat wrpc_abdot2.pid); else P=28487; PID=$(cat wrpc_abdot3.pid); fi
    WPORT=$P python3 -I wprof_drive.py $PID ab_dot3_$arm.csv 8,32,128 1 | sed "s/^/$arm r$r /"
  done
done
for t in abdot2 abdot3; do echo "$t $(grep -E "VmHWM" /proc/$(cat wrpc_$t.pid)/status)"; kill $(cat wrpc_$t.pid); done
sudo cpupower frequency-set -g $gov0 > /dev/null
echo "governor restored to $(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)"
echo AB_DOT3_DONE
